int pptp_connect(struct socket *sock, struct sockaddr *uservaddr, int sockaddr_len, int flags)
{
    int result = -EINVAL;
    struct sock *sk = sock->sk;

    if (sockaddr_len < sizeof(struct sockaddr_in))
        goto out;

    if (uservaddr->sa_family != AF_INET)
        goto out;

    lock_sock(sk);

    if (sock->state != SS_UNCONNECTED || sk->sk_state != TCP_CLOSE)
        goto out_unlock;

    result = ppp_channel_attach(&sk->sk_pptp_chan, &pptp_ioctl_ops);
    if (result < 0)
        goto out_unlock;

    sk->sk_state = TCP_ESTABLISHED;
    sock->state = SS_CONNECTED;

    release_sock(sk);
    return 0;

out_unlock:
    release_sock(sk);
out:
    return result;
}

int pptp_connect(struct socket *sock, struct sockaddr *uservaddr, int sockaddr_len, int flags) {
    int result = -EINVAL;

    if (!sock || !uservaddr || sockaddr_len < sizeof(sa_family_t)) {
        return -EINVAL;
    }

    if (((struct sockaddr_in *)uservaddr)->sin_family != AF_INET) {
        return -EAFNOSUPPORT;
    }

    sock->sk->sk_state = TCP_ESTABLISHED;
    sock->sk->sk_bound_dev_if = 0;

    if (sock->sk->sk_state != TCP_ESTABLISHED || sock->sk->sk_dead) {
        return -EALREADY;
    }

    spin_lock_bh(&sock->sk->sk_lock.slock);

    if (sock->sk->sk_state != TCP_ESTABLISHED || sock->sk->sk_dead) {
        spin_unlock_bh(&sock->sk->sk_lock.slock);
        return -ECONNRESET;
    }

    sock->sk->sk_state = TCP_SYN_SENT;

    result = ppp_register_channel(sock);
    if (result < 0) {
        sock->sk->sk_state = TCP_ESTABLISHED;
        spin_unlock_bh(&sock->sk->sk_lock.slock);
        return result;
    }

    sock->sk->sk_state = TCP_ESTABLISHED;

    spin_unlock_bh(&sock->sk->sk_lock.slock);

    return 0;
}

int pptp_connect(struct socket *sock, struct sockaddr *uservaddr, int sockaddr_len, int flags) {
    int result = -EINVAL;

    if (!sock || !uservaddr || sockaddr_len <= 0) {
        return -EINVAL;
    }

    if (sock->sk->state != TCP_ESTABLISHED) {
        return -ECONNRESET;
    }

    lock_sock(sock->sk);

    if (sock->sk->state == TCP_CLOSE || sock->sk->state == TCP_LISTEN) {
        release_sock(sock->sk);
        return -EALREADY;
    }

    /* Validate protocol type and address family */
    if (uservaddr->sa_family != AF_INET) {
        release_sock(sock->sk);
        return -EAFNOSUPPORT;
    }

    /* Setup PPTP channel and routing */
    result = setup_pptp_channel(sock, uservaddr);
    if (result < 0) {
        release_sock(sock->sk);
        return result;
    }

    /* Adjust MTU as necessary */
    adjust_mtu(sock, uservaddr);

    /* Register PPP channel */
    if (register_ppp_channel(sock) < 0) {
        release_sock(sock->sk);
        return -EIO;
    }

    sock->sk->state = TCP_CONNECTED;
    release_sock(sock->sk);

    return 0;
}

int pptp_connect(struct socket *sock, struct sockaddr *uservaddr, int sockaddr_len, int flags)
{
    int result = -EINVAL;
    struct sock *sk = sock->sk;
    struct pptp_sock *pps = pptp_sk(sk);
    struct net_device *dev;
    struct sockaddr_pptp *addr = (struct sockaddr_pptp *)uservaddr;
    struct ppp_channel *chan;
    int mtu;

    if (sockaddr_len < sizeof(struct sockaddr_pptp))
        return -EINVAL;

    if (addr->saph_addr.sa_family != AF_PPTP)
        return -EAFNOSUPPORT;

    if (sk->sk_state != TCP_CLOSE && sk->sk_state != TCP_LISTEN)
        return -EISCONN;

    lock_sock(sk);

    if (sk->sk_state == TCP_CLOSE) {
        dev = ppp_get_dev_by_name(addr->address);
        if (!dev)
            goto out;

        mtu = dev->mtu;
        chan = ppp_register_channel(mtu, pptp_xmit);
        if (!chan)
            goto out;

        pps->chan = chan;
        pps->dev = dev;
        sk->sk_state = TCP_ESTABLISHED;
        result = 0;
    }

out:
    release_sock(sk);
    return result;
}
